package com.technova.model;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="compra") public class Compra { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_compra") private Long id; @Column(name="numero_compra") private String numeroCompra; private LocalDateTime fecha; @Column(name="id_proveedor") private Long proveedorId; @Column(name="id_usuario") private Long usuarioId; private BigDecimal subtotal,igv,total; private String estado,observacion; public Compra(){} public Long getId(){return id;} public void setId(Long v){id=v;} public String getNumeroCompra(){return numeroCompra;} public void setNumeroCompra(String v){numeroCompra=v;} public LocalDateTime getFecha(){return fecha;} public void setFecha(LocalDateTime v){fecha=v;} public Long getProveedorId(){return proveedorId;} public void setProveedorId(Long v){proveedorId=v;} public Long getUsuarioId(){return usuarioId;} public void setUsuarioId(Long v){usuarioId=v;} public BigDecimal getSubtotal(){return subtotal;} public void setSubtotal(BigDecimal v){subtotal=v;} public BigDecimal getIgv(){return igv;} public void setIgv(BigDecimal v){igv=v;} public BigDecimal getTotal(){return total;} public void setTotal(BigDecimal v){total=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} public String getObservacion(){return observacion;} public void setObservacion(String v){observacion=v;} }
